+PubSubClient mqtt(networkClient);
+uint32_t lastSampleMs = 0;
+uint32_t lastWifiAttemptMs = 0;
+uint32_t lastMqttAttemptMs = 0;
+
+String toHex(const uint8_t *data, size_t length) {
+  static const char digits[] = "0***REDACTED***9ABCDEF";
+  String result;
+  result.reserve(length * 2);
+  for (size_t i = 0; i < length; ++i) {
+    result += digits[data[i] >> 4];
+    result += digits[data[i] & 0x0F];
+  }
+  return result;
+}
+
+uint16_t modbusCrc(const uint8_t *data, size_t length) {
+  uint16_t crc = 0xFFFF;
+  for (size_t i = 0; i < length; ++i) {
+    crc ^= data[i];
+    for (int bit = 0; bit < 8; ++bit) {
+      crc = (crc & 1) ? static_cast<uint16_t>((crc >> 1) ^ 0xA001)
+                      : static_cast<uint16_t>(crc >> 1);
+    }
+  }
+  return crc;
+}
+
+uint16_t readU16(const uint8_t *data) {
+  return static_cast<uint16_t>(data[0] << 8) | data[1];
+}
+
+float readS16Tenths(const uint8_t *data) {
+  const int16_t value = static_cast<int16_t>(readU16(data));
+  return value / 10.0f;
+}
+
+bool parseReading(const uint8_t *response, size_t length, SoilReading &reading) {
+  if (length != kResponseLength || response[0] != 0x02 || response[1] != 0x03 ||
+      response[2] != 16) {
+    return false;
+  }
+  const uint16_t expected = modbusCrc(response, length - 2);
+  const uint16_t received = static_cast<uint16_t>(response[length - 2]) |
+                            static_cast<uint16_t>(response[length - 1] << 8);
+  if (expected != received) {
+    return false;
+  }
+
+  reading.temp = readS16Tenths(&response[3]);
+  reading.moisture = readU16(&response[5]) / 10.0f;
+  reading.ec = readU16(&response[7]);
+  reading.salt = readU16(&response[9]);
+  reading.nitrogen = readU16(&response[11]);
+  reading.phosphorus = readU16(&response[13]);
+  reading.potassium = readU16(&response[15]);
+  reading.ph = readU16(&response[17]) / 10.0f;
+  return true;
+}
+
+bool readSoil(SoilReading &reading) {
+  digitalWrite(kRs485DirectionPin, HIGH);
+  delay(1);
+  Serial1.write(kRequest, sizeof(kRequest));
+  Serial1.flush();
+  delay(1);
+  digitalWrite(kRs485DirectionPin, LOW);
+
+  uint8_t response[64];
+  size_t length = 0;
+  const uint32_t started = millis();
+  while (millis() - started < kSensorTimeoutMs && length < sizeof(response)) {
+    while (Serial1.available() > 0 && length < sizeof(response)) {
+      response[length++] = static_cast<uint8_t>(Serial1.read());
+    }
+    if (length >= kResponseLength) {
+      delay(5);
+      while (Serial1.available() > 0 && length < sizeof(response)) {
+        response[length++] = static_cast<uint8_t>(Serial1.read());
+      }
+      break;
+    }
+    delay(1);
+  }
+
+  Serial.print("SOIL_RAW=");
+  Serial.print(toHex(response, length));
+  Serial.print(" LEN=");
+  Serial.println(length);
+  return parseReading(response, length, reading);
+}
+
+String readingJson(const SoilReading &reading) {
+  String payload;
+  payload.reserve(180);
+  payload += "{\"moisture\":";
+  payload += String(reading.moisture, 1);
+  payload += ",\"temp\":";
+  payload += String(reading.temp, 1);
+  payload += ",\"ec\":";
+  payload += String(reading.ec, 0);
+  payload += ",\"ph\":";
+  payload += String(reading.ph, 1);
+  payload += ",\"salt\":";
+  payload += String(reading.salt, 0);
+  payload += ",\"nitrogen\":";
+  payload += String(reading.nitrogen, 0);
+  payload += ",\"phosphorus\":";
+  payload += String(reading.phosphorus, 0);
+  payload += ",\"potassium\":";
+  payload += String(reading.potassium, 0);
+  payload += "}";
+  return payload;
+}
+
+void startWifi() {
+  lastWifiAttemptMs = millis();
+  Serial.print("WIFI_CONNECTING SSID=");
