+}
+
+bool loadDeviceSettings(DeviceSettings &settings) {
+  settings = defaultDeviceSettings();
+  Preferences preferences;
+  if (!preferences.begin(kNamespace, true)) {
+    return false;
+  }
+  settings.uploadIntervalSec = preferences.getUInt("interval_s", settings.uploadIntervalSec);
+  settings.modbusAddress = preferences.getUChar("modbus_addr", settings.modbusAddress);
+  settings.modbusBaud = preferences.getUInt("modbus_baud", settings.modbusBaud);
+  settings.tempOffsetTenths = preferences.getShort("temp_off_x10", settings.tempOffsetTenths);
+  settings.phOffsetTenths = preferences.getShort("ph_off_x10", settings.phOffsetTenths);
+  preferences.end();
+  return true;
+}
+
+bool saveDeviceSettings(const DeviceSettings &settings) {
+  Preferences preferences;
+  if (!preferences.begin(kNamespace, false)) {
+    return false;
+  }
+  const bool ok = preferences.putUInt("interval_s", settings.uploadIntervalSec) == sizeof(uint32_t) &&
+                  preferences.putUChar("modbus_addr", settings.modbusAddress) == sizeof(uint8_t) &&
+                  preferences.putUInt("modbus_baud", settings.modbusBaud) == sizeof(uint32_t) &&
+                  preferences.putShort("temp_off_x10", settings.tempOffsetTenths) == sizeof(int16_t) &&
+                  preferences.putShort("ph_off_x10", settings.phOffsetTenths) == sizeof(int16_t);
+  preferences.end();
+  return ok;
+}
+
+bool validateDeviceSettings(const DeviceSettings &settings, String &error) {
+  if (settings.uploadIntervalSec < 10 || settings.uploadIntervalSec > 3600) {
+    error = "采样/上报周期必须在 10 到 3600 秒之间。";
+    return false;
+  }
+  if (settings.modbusAddress < 1 || settings.modbusAddress > 247) {
+    error = "Modbus 从站地址必须在 1 到 247 之间。";
+    return false;
+  }
+  if (settings.modbusBaud != 4800 && settings.modbusBaud != 9600 &&
+      settings.modbusBaud != 19200 && settings.modbusBaud != 38400) {
+    error = "Modbus 波特率只支持 4800、9600、19200、38400。";
+    return false;
+  }
+  if (settings.tempOffsetTenths < -200 || settings.tempOffsetTenths > 200) {
+    error = "温度偏移必须在 -20.0 到 20.0 °C 之间。";
