class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        return

    def send_bytes(self, code, content_type, data):
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/":
            self.send_bytes(200, "text/html; charset=utf-8", INDEX.encode())
            return
        if self.path.startswith("/history"):
            encoded = json.dumps({"lines": list(history)}, ensure_ascii=False).encode()
            self.send_bytes(200, "application/json; charset=utf-8", encoded)
            return
        if self.path == "/events":
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection", "keep-alive")
            self.end_headers()
            client = queue.Queue(maxsize=1000)
            with clients_lock:
                clients.add(client)
                snapshot = list(history)
            try:
                for line in snapshot:
                    self.wfile.write(("data: " + json.dumps({"line": line}, ensure_ascii=False) + "\n\n").encode())
                self.wfile.flush()
                while True:
                    try:
                        payload = client.get(timeout=15)
                        self.wfile.write(("data: " + payload.strip() + "\n\n").encode())
                    except queue.Empty:
                        self.wfile.write(b": keepalive\n\n")
                    self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError):
                pass
            finally:
                with clients_lock:
                    clients.discard(client)
            return
        self.send_bytes(404, "text/plain", b"not found")

    def do_POST(self):
        if self.path != "/send":
            self.send_bytes(404, "text/plain", b"not found")
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            body = json.loads(self.rfile.read(length) or b"{}")
