String toHex(const uint8_t *data, size_t length) {
  static const char digits[] = "0***REDACTED***9ABCDEF";
  String result;
  result.reserve(length * 2);
  for (size_t i = 0; i < length; ++i) {
    result += digits[data[i] >> 4];
    result += digits[data[i] & 0x0F];
  }
  return result;
}

uint16_t modbusCrc(const uint8_t *data, size_t length) {
  uint16_t crc = 0xFFFF;
  for (size_t i = 0; i < length; ++i) {
    crc ^= data[i];
    for (int bit = 0; bit < 8; ++bit) {
      crc = (crc & 1) ? static_cast<uint16_t>((crc >> 1) ^ 0xA001)
                      : static_cast<uint16_t>(crc >> 1);
    }
  }
  return crc;
}

uint16_t readU16(const uint8_t *data) {
  return static_cast<uint16_t>(data[0] << 8) | data[1];
}

float readS16Tenths(const uint8_t *data) {
  const int16_t value = static_cast<int16_t>(readU16(data));
  return value / 10.0f;
}

bool parseReading(const uint8_t *response, size_t length, SoilReading &reading) {
  if (length != kResponseLength || response[0] != 0x02 || response[1] != 0x03 ||
      response[2] != 16) {
    return false;
  }
  const uint16_t expected = modbusCrc(response, length - 2);
  const uint16_t received = static_cast<uint16_t>(response[length - 2]) |
                            static_cast<uint16_t>(response[length - 1] << 8);
  if (expected != received) {
    return false;
  }

  reading.temp = readS16Tenths(&response[3]);
  reading.moisture = readU16(&response[5]) / 10.0f;
  reading.ec = readU16(&response[7]);
  reading.salt = readU16(&response[9]);
  reading.nitrogen = readU16(&response[11]);
  reading.phosphorus = readU16(&response[13]);
  reading.potassium = readU16(&response[15]);
  reading.ph = readU16(&response[17]) / 10.0f;
  return true;
}

bool readSoil(const DeviceSettings &settings, SoilReading &reading) {
  uint8_t request[] = {settings.modbusAddress, 0x03, 0x00, 0x00, 0x00, 0x08, 0x00, 0x00};
  const uint16_t requestCrc = modbusCrc(request, 6);
  request[6] = requestCrc & 0xFF;
  request[7] = requestCrc >> 8;

  digitalWrite(kRs485DirectionPin, HIGH);
  delay(1);
  Serial1.write(request, sizeof(request));
  Serial1.flush();
  delay(1);
  digitalWrite(kRs485DirectionPin, LOW);

  uint8_t response[64];
  size_t length = 0;
  const uint32_t started = millis();
  while (millis() - started < kSensorTimeoutMs && length < sizeof(response)) {
    while (Serial1.available() > 0 && length < sizeof(response)) {
      response[length++] = static_cast<uint8_t>(Serial1.read());
    }
    if (length >= kResponseLength) {
      delay(5);
      while (Serial1.available() > 0 && length < sizeof(response)) {
        response[length++] = static_cast<uint8_t>(Serial1.read());
      }
      break;
    }
    delay(1);
  }

  Serial.print("SOIL_RAW=");
  Serial.print(toHex(response, length));
  Serial.print(" LEN=");
  Serial.println(length);
  if (!parseReading(response, length, reading)) {
    return false;
  }
  reading.temp += settings.tempOffsetTenths / 10.0f;
  reading.ph += settings.phOffsetTenths / 10.0f;
  return true;
}

String readingJson(const SoilReading &reading) {
  String payload;
  payload.reserve(180);
  payload += "{\"moisture\":";
  payload += String(reading.moisture, 1);
  payload += ",\"temp\":";
  payload += String(reading.temp, 1);
  payload += ",\"ec\":";
  payload += String(reading.ec, 0);
  payload += ",\"ph\":";
  payload += String(reading.ph, 1);
  payload += ",\"salt\":";
  payload += String(reading.salt, 0);
  payload += ",\"nitrogen\":";
  payload += String(reading.nitrogen, 0);
  payload += ",\"phosphorus\":";
  payload += String(reading.phosphorus, 0);
  payload += ",\"potassium\":";
  payload += String(reading.potassium, 0);
  payload += "}";
  return payload;
}

bool waitForWifiConnection(uint32_t timeoutMs) {
  const uint32_t started = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - started < timeoutMs) {
    delay(100);
  }
  if (WiFi.status() == WL_CONNECTED) {
    WiFi.setSleep(true);
    return true;
  }
  return false;
}

bool tryWifiBegin(const WifiCredentials &credentials, int32_t channel,
                  const uint8_t *bssid, uint32_t timeoutMs) {
  WiFi.disconnect(false, false);
  delay(300);
  if (bssid != nullptr && channel > 0) {
    WiFi.begin(credentials.ssid.c_str(), credentials.password.c_str(), channel, bssid);
  } else {
    WiFi.begin(credentials.ssid.c_str(), credentials.password.c_str());
  }
  return waitForWifiConnection(timeoutMs);
}

bool connectWifi(const WifiCredentials &credentials) {
  Serial.print("WIFI_CONNECTING SSID=");
  Serial.println(credentials.ssid);
  WiFi.persistent(false);
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);
  WiFi.setSleep(false);

  if (credentials.hasBssid) {
    Serial.println("WIFI_FAST_HINT");
    if (tryWifiBegin(credentials, credentials.channel, credentials.bssid, 10000)) {
      return true;
    }
  }

  int targetChannel = 0;
  uint8_t targetBssid[6] = {};
  bool hasTargetBssid = false;
  const int scanCount = WiFi.scanNetworks(false, true);
  int bestRssi = -1000;
  for (int i = 0; i < scanCount; ++i) {
    if (WiFi.SSID(i) == credentials.ssid && WiFi.RSSI(i) > bestRssi) {
      bestRssi = WiFi.RSSI(i);
      targetChannel = WiFi.channel(i);
      memcpy(targetBssid, WiFi.BSSID(i), sizeof(targetBssid));
      hasTargetBssid = true;
    }
  }
  WiFi.scanDelete();
  if (hasTargetBssid) {
    Serial.print("WIFI_TARGET channel=");
    Serial.print(targetChannel);
    Serial.print(" rssi=");
    Serial.println(bestRssi);
    if (tryWifiBegin(credentials, targetChannel, targetBssid, kWifiTimeoutMs)) {
      saveWifiConnectionHint(targetBssid, targetChannel);
      return true;
    }
  }

  Serial.println("WIFI_GENERIC_ATTEMPT");
  return tryWifiBegin(credentials, 0, nullptr, kWifiTimeoutMs);
}

bool connectMqtt() {
  Serial.print("MQTT_CONNECTING ");
  Serial.print(kMqttHost);
  Serial.print(":");
  Serial.println(kMqttPort);
  const bool connected = mqtt.connect(kMqttClientId, kMqttUser, kMqttPassword);
  Serial.print("MQTT_CONNECTED=");
  Serial.println(connected ? "true" : "false");
  return connected;
}

void publishReading(const SoilReading &reading) {
  const String payload = readingJson(reading);
  Serial.print("SOIL_JSON=");
  Serial.println(payload);
  if (!mqtt.connected()) {
    Serial.println("MQTT_PUBLISH_SKIPPED offline");
    return;
  }
  const bool published = mqtt.publish(kMqttTopic, payload.c_str(), false);
  Serial.print("MQTT_PUBLISH=");
  Serial.print(published ? "OK" : "FAIL");
  Serial.print(" TOPIC=");
  Serial.println(kMqttTopic);
}

[[noreturn]] void deepSleepFor(uint64_t durationMs) {
  WiFi.disconnect(true, false);
  WiFi.mode(WIFI_OFF);
  Serial.print("DEEP_SLEEP_MS=");
  Serial.println(static_cast<uint32_t>(durationMs));
  Serial.flush();
  esp_sleep_enable_timer_wakeup(durationMs * 1000ULL);
  esp_deep_sleep_start();
}

[[noreturn]] void finishCycle(uint32_t cycleStartedMs, uint32_t intervalMs) {
  if (mqtt.connected()) {
    mqtt.disconnect();
  }
  const uint32_t activeMs = millis() - cycleStartedMs;
  const uint32_t remainingMs = activeMs < intervalMs ? intervalMs - activeMs : 5000;
  deepSleepFor(remainingMs);
}
