  if (!validateDeviceSettings(settings, error)) {
    sendResult(false, "参数无效", error);
    return;
  }

  if (!connectToSubmittedNetwork(ssid, password)) {
    sendResult(false, "连接失败", "无法连接 Wi-Fi 或无法访问 MQTT 云端。请检查密码、2.4 GHz 频段和网络访问权限后重试。");
    return;
  }
  if (!saveWifiCredentials(ssid, password) || !saveDeviceSettings(settings)) {
    sendResult(false, "保存失败", "网络连接成功，但写入设备配置失败，请重试。");
    return;
  }
  configurationComplete = true;
  sendResult(true, "配置成功", "设备正在重启，随后会按新周期开始采集和上报。");
  return;
}

void handleReset() {
  clearWifiCredentials();
  clearDeviceSettings();
  sendResult(true, "配置已清除", "设备正在重启并进入配网模式。");
  configurationComplete = true;
}
