bool loadWifiCredentials(WifiCredentials &credentials) {
  Preferences preferences;
  if (!preferences.begin("wifi", true)) {
    return false;
  }
  credentials.ssid = preferences.getString("ssid", "");
  credentials.password = preferences.getString("password", "");
  credentials.channel = preferences.getInt("channel", 0);
  const size_t bssidLength = preferences.getBytes("bssid", credentials.bssid, sizeof(credentials.bssid));
  credentials.hasBssid = bssidLength == sizeof(credentials.bssid) && credentials.channel > 0;
  preferences.end();
  return !credentials.ssid.isEmpty();
}

bool saveWifiCredentials(const String &ssid, const String &password) {
  Preferences preferences;
  if (!preferences.begin("wifi", false)) {
    return false;
  }
  const bool ok = preferences.putString("ssid", ssid) == ssid.length() &&
                  preferences.putString("password", password) == password.length() &&
                  preferences.putUChar("channel", 0) == sizeof(uint8_t);
  const uint8_t emptyBssid[6] = {};
  const bool hintCleared = preferences.putBytes("bssid", emptyBssid, sizeof(emptyBssid)) == sizeof(emptyBssid);
  preferences.end();
  return ok && hintCleared;
}

bool saveWifiConnectionHint(const uint8_t bssid[6], int32_t channel) {
  Preferences preferences;
  if (!preferences.begin("wifi", false)) {
    return false;
  }
  const bool ok = preferences.putInt("channel", channel) == sizeof(int32_t) &&
                  preferences.putBytes("bssid", bssid, 6) == 6;
  preferences.end();
  return ok;
}

void clearWifiCredentials() {
  Preferences preferences;
  if (preferences.begin("wifi", false)) {
    preferences.clear();
    preferences.end();
  }
}

String provisioningApSsid() {
  return "ZXB-Soil-" + deviceSuffix();
}

bool runProvisioningPortal(uint32_t timeoutMs) {
  WiFi.persistent(false);
  WiFi.mode(WIFI_AP);
  const String apSsid = provisioningApSsid();
  if (!WiFi.softAP(apSsid.c_str())) {
    return false;
  }

  webServer.on("/", HTTP_GET, sendPortalPage);
  webServer.on("/scan", HTTP_GET, handleScan);
  webServer.on("/settings", HTTP_GET, handleSettings);
  webServer.on("/save", HTTP_POST, handleSave);
  webServer.on("/reset", HTTP_POST, handleReset);
  webServer.onNotFound([]() {
    webServer.sendHeader("Location", "http://192.168.4.1/", true);
    webServer.send(302, "text/plain; charset=utf-8", "");
  });
  webServer.begin();
  dnsServer.start(53, "*", WiFi.softAPIP());

  Serial.print("PROVISIONING_AP SSID=");
  Serial.print(apSsid);
  Serial.print(" URL=http://");
  Serial.println(WiFi.softAPIP());

  configurationComplete = false;
  const uint32_t started = millis();
  while (!configurationComplete && millis() - started < timeoutMs) {
    dnsServer.processNextRequest();
    webServer.handleClient();
    delay(2);
  }

  if (configurationComplete) {
    delay(1200);
    ESP.restart();
  }

  webServer.stop();
  dnsServer.stop();
  WiFi.softAPdisconnect(true);
  WiFi.mode(WIFI_OFF);
  return false;
}
