SERIAL_PORT = os.environ.get("COM_CONSOLE_PORT_NAME", "COM11")
BAUD_RATE = int(os.environ.get("COM_CONSOLE_BAUD", "115200"))
MAX_HISTORY = int(os.environ.get("COM_CONSOLE_MAX_HISTORY", str(8 * 1024 * 1024)))

history = bytearray()
history_lock = threading.Lock()
subscribers: set[queue.Queue] = set()
subscribers_lock = threading.Lock()
connection_state = {
    "connected": False,
    "port": SERIAL_PORT,
    "baud": BAUD_RATE,
    "error": "starting",
}
state_lock = threading.Lock()
total_bytes = 0
server_started = time.time()


def snapshot_state() -> dict:
    with state_lock:
        state = dict(connection_state)
    state["total_bytes"] = total_bytes
    state["server_started"] = server_started
    return state


def set_state(**values) -> None:
    with state_lock:
        connection_state.update(values)
    event = {"type": "status", "state": snapshot_state()}
    broadcast(event, raw=None)


def append_history(data: bytes) -> None:
    global total_bytes
    total_bytes += len(data)
    with history_lock:
        history.extend(data)
        if len(history) > MAX_HISTORY:
            del history[: len(history) - MAX_HISTORY]
    broadcast({"type": "data", "b64": base64.b64encode(data).decode("ascii")}, raw=data)


def broadcast(event: dict, raw: bytes | None) -> None:
    message = json.dumps(event, separators=(",", ":"))
    with subscribers_lock:
        dead = []
        for target in subscribers:
            try:
                target.put_nowait(message)
            except queue.Full:
                dead.append(target)
        for target in dead:
            subscribers.discard(target)


