 360: static bool handle_request(int fd, const char *request,
 361:                            struct soil_settings_s *settings)
 362: {
 363:   char method[16];
 364:   char path[128];
 365:   const char *body;
 366:   const char *header_end;
 367: 
 368:   if (sscanf(request, "%15s %127s", method, path) != 2)
 369:     {
 370:       send_response(fd, 400, "text/plain; charset=utf-8", "无效请求");
 371:       return false;
 372:     }
 373: 
 374:   header_end = strstr(request, "\r\n\r\n");
 375:   body = header_end == NULL ? "" : header_end + 4;
 376: 
 377:   if (strcmp(method, "GET") == 0 && strcmp(path, "/") == 0)
 378:     {
 379:       send_response(fd, 200, "text/html; charset=utf-8", g_portal_page);
 380:     }
 381:   else if (strcmp(method, "GET") == 0 &&
 382:            strcmp(path, "/api/settings") == 0)
 383:     {
 384:       handle_settings(fd, settings);
 385:     }
 386:   else if (strcmp(method, "GET") == 0 && strcmp(path, "/api/scan") == 0)
 387:     {
 388:       handle_scan(fd);
 389:     }
 390:   else if (strcmp(method, "POST") == 0 && strcmp(path, "/api/save") == 0)
 391:     {
 392:       return handle_save(fd, body, settings);
 393:     }
 394:   else if (strcmp(method, "POST") == 0 && strcmp(path, "/api/reset") == 0)
 395:     {
 396:       soil_settings_clear();
 397:       soil_defaults(settings);
 398:       send_response(fd, 200, "text/plain; charset=utf-8", "配置已清除");
 399:     }
 400:   else
 401:     {
 402:       redirect_to_portal(fd);
 403:     }
 404: 
 405:   return false;
 406: }
