static void json_escape(char *dest, size_t dest_size, const char *source)
{
  size_t out = 0;

  while (*source != '\0' && out + 1 < dest_size)
    {
      unsigned char ch = (unsigned char)*source++;
      if (ch == '"' || ch == '\\')
        {
          if (out + 2 >= dest_size)
            {
              break;
            }

          dest[out++] = '\\';
          dest[out++] = (char)ch;
        }
      else if (ch >= 0x20)
        {
          dest[out++] = (char)ch;
        }
    }

  dest[out] = '\0';
}

int soil_wifi_station_connect(const struct soil_settings_s *settings,
                              char *ip, size_t ip_size)
{
  struct in_addr address;
  int sock;
  int ret;
  int attempt;

  memset(&address, 0, sizeof(address));
  if (ip != NULL && ip_size > 0)
    {
      ip[0] = '\0';
    }

  {
    char *const ifdown_argv[] = {"ifdown", SOIL_WIFI_STA_IF, NULL};
    char *const ifup_argv[] = {"ifup", SOIL_WIFI_STA_IF, NULL};
    char *const mode_argv[] =
      {"wapi", "mode", SOIL_WIFI_STA_IF, "2", NULL};
    char *const essid_argv[] =
      {"wapi", "essid", SOIL_WIFI_STA_IF,
       (char *)settings->wifi_ssid, "1", NULL};

    run_builtin(ifdown_argv);
    run_builtin(ifup_argv);
    run_builtin(mode_argv);

    if (settings->wifi_password[0] != '\0')
      {
        char *const psk_argv[] =
          {"wapi", "psk", SOIL_WIFI_STA_IF,
           (char *)settings->wifi_password, "3", NULL};
        run_builtin(psk_argv);
      }

    ret = run_builtin(essid_argv);
  }

  if (ret < 0)
    {
      return ret;
    }

  netlib_ifup(SOIL_WIFI_STA_IF);
  sleep(1);

  {
    char *const renew_argv[] = {"renew", SOIL_WIFI_STA_IF, NULL};
    run_builtin(renew_argv);
  }

  sock = wapi_make_socket();
  if (sock < 0)
    {
      return sock;
    }

  for (attempt = 0; attempt < 20; attempt++)
    {
      ret = wapi_get_ip(sock, SOIL_WIFI_STA_IF, &address);
      if (ret == 0 && address.s_addr != 0)
        {
          break;
        }

      sleep(1);
    }

  if (address.s_addr == 0)
    {
      close(sock);
      return -ETIMEDOUT;
    }

  wapi_set_power_save(sock, SOIL_WIFI_STA_IF, settings->power_save);
  if (ip != NULL && ip_size > 0)
    {
      inet_ntop(AF_INET, &address, ip, ip_size);
    }

  close(sock);
  return 0;
}

bool soil_wifi_station_is_connected(void)
{
  struct in_addr address;
  int sock;
  int ret;

  sock = wapi_make_socket();
  if (sock < 0)
    {
      return false;
    }

  memset(&address, 0, sizeof(address));
  ret = wapi_get_ip(sock, SOIL_WIFI_STA_IF, &address);
  close(sock);
  return ret == 0 && address.s_addr != 0;
}

