import machine
import time

lines = []


def crc16(data):
    crc = 0xFFFF
    for value in data:
        crc ^= value
        for _ in range(8):
            crc = (crc >> 1) ^ 0xA001 if crc & 1 else crc >> 1
    return crc


def request_for(address):
    body = bytes([address, 0x03, 0x00, 0x00, 0x00, 0x08])
    crc = crc16(body)
    return body + bytes([crc & 0xFF, crc >> 8])


def attempt(uart_id, address, tx_pin, rx_pin, invert, label):
    uart = None
    data = bytearray()
    try:
        kwargs = dict(
            baudrate=9600,
            bits=8,
            parity=None,
            stop=1,
            tx=tx_pin,
            rx=rx_pin,
        )
        if invert:
            kwargs["invert"] = invert
        uart = machine.UART(uart_id, **kwargs)
        uart.write(request_for(address))
        deadline = time.ticks_add(time.ticks_ms(), 400)
        while time.ticks_diff(deadline, time.ticks_ms()) > 0:
            chunk = uart.read(64)
