"""Read Modbus addresses 1/2 on RS485 port 1 using GPIO18/GPIO19."""

import machine
import time

GPIO18 = 18
GPIO19 = 19
DIRECTION_PINS = (0, 2, 4, 5, 12, 13, 14, 15, 16, 17, 21, 22, 23, 25, 26, 27, 32, 33)
lines = []


def crc16(data):
    crc = 0xFFFF
    for value in data:
        crc ^= value
        for _ in range(8):
            crc = (crc >> 1) ^ 0xA001 if crc & 1 else crc >> 1
    return crc


def request_for(address):
    body = bytes([address, 0x03, 0x00, 0x00, 0x00, 0x08])
    crc = crc16(body)
    return body + bytes([crc & 0xFF, crc >> 8])


def attempt(address, tx_pin, rx_pin, mode):
    uart = None
    outputs = []
    data = bytearray()
    try:
        if mode in ("high", "low"):
            value = 1 if mode == "high" else 0
            for pin in DIRECTION_PINS:
                outputs.append(machine.Pin(pin, machine.Pin.OUT, value=value))
        uart = machine.UART(2, baudrate=9600, bits=8, parity=None, stop=1, tx=tx_pin, rx=rx_pin)
        uart.write(request_for(address))
        time.sleep_ms(20)
        if mode in ("high", "low"):
            for pin in outputs:
                pin.value(0 if mode == "high" else 1)
        deadline = time.ticks_add(time.ticks_ms(), 500)
        while time.ticks_diff(deadline, time.ticks_ms()) > 0:
            chunk = uart.read(64)
            if chunk:
                data.extend(chunk)
            else:
                time.sleep_ms(5)
        tag = "addr%s-tx%s-rx%s-%s" % (address, tx_pin, rx_pin, mode)
        lines.append(tag + "=" + (data.hex() if data else "EMPTY"))
    except Exception as exc:
        tag = "addr%s-tx%s-rx%s-%s" % (address, tx_pin, rx_pin, mode)
        lines.append(tag + "=ERROR:%r" % (exc,))
    finally:
        if uart is not None:
            uart.deinit()
        for pin in outputs:
            try:
                pin.init(machine.Pin.IN)
            except Exception:
                pass


for address in (1, 2):
    for tx_pin, rx_pin in ((GPIO18, GPIO19), (GPIO19, GPIO18)):
        for mode in ("auto", "high", "low"):
            attempt(address, tx_pin, rx_pin, mode)

with open("/rs485_port1_result.txt", "w") as handle:
    handle.write(";".join(lines))
time.sleep_ms(100)
machine.reset()

