+String toHex(const uint8_t *data, size_t length) {
+  static const char digits[] = "0***REDACTED***9ABCDEF";
+  String result;
+  result.reserve(length * 2);
+  for (size_t i = 0; i < length; ++i) {
+    result += digits[data[i] >> 4];
+    result += digits[data[i] & 0x0F];
+  }
+  return result;
+}
+
+uint16_t crc16(const uint8_t *data, size_t length) {
+  uint16_t crc = 0xFFFF;
+  for (size_t i = 0; i < length; ++i) {
+    crc ^= data[i];
+    for (int bit = 0; bit < 8; ++bit) {
+      crc = (crc & 1) ? static_cast<uint16_t>((crc >> 1) ^ 0xA001)
+                      : static_cast<uint16_t>(crc >> 1);
+    }
+  }
+  return crc;
+}
+
+void sample(uint8_t address) {
+  uint8_t request[] = {address, 0x03, 0x00, 0x00, 0x00, 0x08, 0, 0};
+  const uint16_t crc = crc16(request, 6);
+  request[6] = crc & 0xFF;
+  request[7] = crc >> 8;
+
+  while (Serial1.available() > 0) {
+    Serial1.read();
+  }
+
