+  delay(1);
+  Serial1.write(request, sizeof(request));
+  Serial1.flush();
+  delay(2);
+  digitalWrite(kDirectionPin, LOW);
+
+  uint8_t response[64];
+  size_t length = 0;
+  const uint32_t started = millis();
+  while (millis() - started < 1200 && length < sizeof(response)) {
+    while (Serial1.available() > 0 && length < sizeof(response)) {
+      response[length++] = static_cast<uint8_t>(Serial1.read());
+    }
+    delay(1);
+  }
+
+  Serial.printf("ADDR=%u RAW=%s LEN=%u\n", address,
