[[noreturn]] void finishCycle(uint32_t cycleStartedMs, uint32_t intervalMs) {
  if (mqtt.connected()) {
    mqtt.disconnect();
  }
  const uint32_t activeMs = millis() - cycleStartedMs;
  const uint32_t remainingMs = activeMs < intervalMs ? intervalMs - activeMs : 5000;
  deepSleepFor(remainingMs);
}
