int soil_power_deep_sleep_us(uint64_t duration_us)
{
#ifdef CONFIG_ARCH_CHIP_ESP32
  const uint32_t pd_flags = SOIL_RTC_SLEEP_PD_DIG |
                            SOIL_RTC_SLEEP_PD_RTC_PERIPH |
                            SOIL_RTC_SLEEP_PD_RTC_SLOW_MEM |
                            SOIL_RTC_SLEEP_PD_RTC_FAST_MEM |
                            SOIL_RTC_SLEEP_PD_VDDSDIO |
                            SOIL_RTC_SLEEP_PD_MODEM |
                            SOIL_RTC_SLEEP_PD_XTAL |
                            SOIL_RTC_SLEEP_PD_INT_8M;
  uint32_t period = *(volatile uint32_t *)SOIL_RTC_SLOW_CLK_CAL_REG;
  uint64_t now;
  uint64_t delta;
  irqstate_t irq_flags;
  int ret;

  if (period == 0)
    {
      /* OpenVela does not populate the calibration store on this board.
       * The deep-sleep counter runs from the configured 10 MHz RTC clock.
       */

      period = (1u << 19) / 10u;
    }

  netlib_ifdown("wlan0");
  netlib_ifdown("wlan1");
  fflush(stdout);

  now = esp32_rtc_time_get();
  delta = esp32_rtc_time_us_to_slowclk(duration_us, period);
  soil_log("DEEP_SLEEP_RTC period=%lu now=%llu delta=%llu\n",
           (unsigned long)period, (unsigned long long)now,
           (unsigned long long)delta);
  esp32_rtc_sleep_init(pd_flags);
  esp32_rtc_sleep_set_wakeup_time(now + delta);
  esp32_rtc_cpu_freq_set_xtal();

  irq_flags = up_irq_save();
  ret = esp32_rtc_sleep_start(SOIL_RTC_TIMER_TRIG_EN, 0);
  up_irq_restore(irq_flags);

  soil_log("DEEP_SLEEP_REJECTED ret=%d\n", ret);

  return ret == 0 ? -EIO : 0;
#else
  return -ENOTSUP;
#endif
}

