namespace {
constexpr int kUart1RxPin = 19;
constexpr int kUart1TxPin = 18;
constexpr int kRs485DirectionPin = 5;
constexpr uint32_t kSensorTimeoutMs = 600;
constexpr uint32_t kWifiTimeoutMs = 15000;
constexpr uint32_t kProvisioningTimeoutMs = 3 * 60 * 1000;
constexpr uint32_t kProvisioningRetrySleepMs = 30 * 60 * 1000;
constexpr size_t kResponseLength = 21;

struct SoilReading {
  float moisture;
  float temp;
  float ec;
  float ph;
  float salt;
  float nitrogen;
  float phosphorus;
  float potassium;
};

