  if (!loadWifiCredentials(credentials)) {
    Serial.println("WIFI_CREDENTIALS_EMPTY_START_PROVISIONING");
    runProvisioningPortal(kProvisioningTimeoutMs);
    Serial.println("PROVISIONING_TIMEOUT_SLEEP_30_MIN");
    deepSleepFor(kProvisioningRetrySleepMs);
  }

  if (!connectWifi(credentials)) {
    Serial.println("WIFI_CONNECT_TIMEOUT");
    WiFi.disconnect(true, false);
    WiFi.mode(WIFI_OFF);
    Serial.print("PROVISIONING_START TIMEOUT_MIN=");
    Serial.println(kProvisioningTimeoutMs / 60000);
    runProvisioningPortal(kProvisioningTimeoutMs);
    Serial.println("PROVISIONING_TIMEOUT_SLEEP_30_MIN");
    deepSleepFor(kProvisioningRetrySleepMs);
  }

  Serial.print("WIFI_CONNECTED IP=");
  Serial.println(WiFi.localIP());

  SoilReading reading{};
  if (!readSoil(settings, reading)) {
    Serial.println("SOIL_READ_FAILED");
    finishCycle(cycleStartedMs, settings.uploadIntervalSec * 1000UL);
  }

  Serial.print("SOIL_OK moisture=");
  Serial.print(reading.moisture, 1);
  Serial.print(" temp=");
  Serial.print(reading.temp, 1);
  Serial.print(" ec=");
  Serial.print(reading.ec, 0);
  Serial.print(" ph=");
  Serial.print(reading.ph, 1);
  Serial.print(" salt=");
  Serial.print(reading.salt, 0);
  Serial.print(" n=");
  Serial.print(reading.nitrogen, 0);
  Serial.print(" p=");
  Serial.print(reading.phosphorus, 0);
  Serial.print(" k=");
  Serial.println(reading.potassium, 0);

  if (!connectMqtt()) {
    Serial.println("MQTT_CONNECT_FAILED");
    finishCycle(cycleStartedMs, settings.uploadIntervalSec * 1000UL);
  }
  mqtt.loop();
  publishReading(reading);
  delay(250);
  mqtt.loop();
  finishCycle(cycleStartedMs, settings.uploadIntervalSec * 1000UL);
}

