bool loadWifiCredentials(WifiCredentials &credentials) {
  Preferences preferences;
  if (!preferences.begin("wifi", true)) {
    return false;
  }
  credentials.ssid = preferences.getString("ssid", "");
  credentials.password = preferences.getString("password", "");
  credentials.channel = preferences.getInt("channel", 0);
  const size_t bssidLength = preferences.getBytes("bssid", credentials.bssid, sizeof(credentials.bssid));
  credentials.hasBssid = bssidLength == sizeof(credentials.bssid) && credentials.channel > 0;
  preferences.end();
  return !credentials.ssid.isEmpty();
}

bool saveWifiCredentials(const String &ssid, const String &password) {
  Preferences preferences;
  if (!preferences.begin("wifi", false)) {
    return false;
  }
  const bool ok = preferences.putString("ssid", ssid) == ssid.length() &&
                  preferences.putString("password", password) == password.length() &&
                  preferences.putUChar("channel", 0) == sizeof(uint8_t);
  const uint8_t emptyBssid[6] = {};
  const bool hintCleared = preferences.putBytes("bssid", emptyBssid, sizeof(emptyBssid)) == sizeof(emptyBssid);
  preferences.end();
  return ok && hintCleared;
}

bool saveWifiConnectionHint(const uint8_t bssid[6], int32_t channel) {
  Preferences preferences;
  if (!preferences.begin("wifi", false)) {
    return false;
  }
  const bool ok = preferences.putInt("channel", channel) == sizeof(int32_t) &&
                  preferences.putBytes("bssid", bssid, 6) == 6;
  preferences.end();
  return ok;
}

void clearWifiCredentials() {
  Preferences preferences;
