      char json[4096];

      ret = soil_wifi_scan_json(json, sizeof(json));
      soil_log("WIFI_SCAN_RESULT=%s ret=%d\n",
               ret == 0 ? "OK" : "FAIL", ret);
      if (ret == 0)
        {
          soil_log("WIFI_SCAN_JSON=%s\n", json);
