      soil_log("PORTAL_RESULT=%d\n", ret);
      return ret;
    }

  if (argc > 2 && strcmp(argv[1], "sleep-test") == 0)
    {
      unsigned long seconds = strtoul(argv[2], NULL, 10);

      if (seconds < 2 || seconds > 3600)
