          return -EINVAL;
        }

      soil_log("DEEP_SLEEP_TEST seconds=%lu\n", seconds);
      ret = soil_power_deep_sleep_us((uint64_t)seconds * 1000000ULL);
      soil_log("DEEP_SLEEP_TEST_FAILED ret=%d\n", ret);
      return ret;
    }

