{
  struct iwreq wrq =
  {
  };

  int ret;

  strlcpy(wrq.ifr_name, ifname, IFNAMSIZ);
  ret = ioctl(sock, SIOCGIWSENS, (unsigned long)((uintptr_t)&wrq));
