static int send_all(int fd, const void *data, size_t length)
{
  const uint8_t *bytes = data;
  size_t sent = 0;

  while (sent < length)
    {
      ssize_t ret = send(fd, bytes + sent, length - sent, 0);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (ret == 0)
        {
          return -EIO;
        }

      sent += (size_t)ret;
    }

  return 0;
}

