    {
      struct ether_addr ap;
      double frequency = 0;
      enum wapi_freq_flag_e frequency_flag = WAPI_FREQ_AUTO;
      int channel = 0;

      if (wapi_get_ap(sock, SOIL_WIFI_STA_IF, &ap) == 0 &&
          wapi_get_freq(sock, SOIL_WIFI_STA_IF, &frequency,
                        &frequency_flag) == 0 &&
          wapi_freq2chan(sock, SOIL_WIFI_STA_IF, frequency, &channel) == 0 &&
