<script>
const term=document.getElementById('term'),statusEl=document.getElementById('status'),dot=document.getElementById('dot'),rateEl=document.getElementById('rate'),errorEl=document.getElementById('error');
const composer=document.getElementById('composer'),command=document.getElementById('command');
let paused=false,autoScroll=true,decoder=new TextDecoder('utf-8');
let total=0,lastSample=Date.now(),lastTotal=0;
function appendBytes(bytes){const text=decoder.decode(bytes,{stream:true});if(!paused){term.textContent+=text}}
function bytesFromB64(b64){const bin=atob(b64),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
function updateRate(){const now=Date.now();if(now-lastSample>500){const bps=(total-lastTotal)*1000/(now-lastSample);rateEl.textContent=Math.round(bps)+' B/s · '+total+' B';lastTotal=total;lastSample=now}}
setInterval(()=>{updateRate();if(autoScroll)term.scrollTop=term.scrollHeight},250);
document.getElementById('pause').onclick=e=>{paused=!paused;e.target.classList.toggle('active',paused);e.target.textContent=paused?'继续':'暂停'};
document.getElementById('autoscroll').onclick=e=>{autoScroll=!autoScroll;e.target.classList.toggle('active',autoScroll)};
document.getElementById('clear').onclick=()=>{term.textContent=''};
document.getElementById('download').onclick=()=>{const blob=new Blob([term.textContent],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='com11-debug.log';a.click()};
async function sendCommand(text){if(!text)return;const response=await fetch('/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:text+'\r\n'})});if(!response.ok){errorEl.textContent='发送失败: '+await response.text()}}
composer.onsubmit=e=>{e.preventDefault();sendCommand(command.value);command.value=''};
document.querySelectorAll('[data-command]').forEach(button=>button.onclick=()=>sendCommand(button.dataset.command));
const es=new EventSource('/events');
es.onopen=()=>{statusEl.textContent='已连接';dot.classList.add('ok')};
es.onerror=()=>{statusEl.textContent='重连中';dot.classList.remove('ok')};
es.onmessage=e=>{try{const event=JSON.parse(e.data);if(event.type==='data'){appendBytes(bytesFromB64(event.b64));total+=Math.floor(event.b64.length*3/4)}else if(event.type==='status'){const s=event.state;statusEl.textContent=s.connected?'串口已连接':'串口未连接';dot.classList.toggle('ok',s.connected);errorEl.textContent=s.error||'';}}catch(err){statusEl.textContent='数据解析错误';}};
</script>
